package com.rafat.munasabati;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.os.Build;import java.util.*;
public class LocationReminderReceiver extends BroadcastReceiver{
 @Override public void onReceive(Context c,Intent i){try{if(c.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&c.checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){V4Log.error(c,"location","Location permission missing");LocationReminderScheduler.schedule(c);return;}LocationManager lm=(LocationManager)c.getSystemService(Context.LOCATION_SERVICE);Location best=null;for(String p:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER}){try{Location x=lm.getLastKnownLocation(p);if(x!=null&&(best==null||x.getTime()>best.getTime()))best=x;}catch(Exception ignored){}}if(best==null){V4Log.error(c,"location","No recent location available");LocationReminderScheduler.schedule(c);return;}for(EventStore.Event e:EventStore.load(c)){V4Meta.Meta m=V4Meta.get(c,e.id);if("none".equals(m.locationReminder)||Double.isNaN(m.locationLat)||Double.isNaN(m.locationLng))continue;float[] out=new float[1];Location.distanceBetween(best.getLatitude(),best.getLongitude(),m.locationLat,m.locationLng,out);boolean inside=out[0]<=m.locationRadius,fire=("arrive".equals(m.locationReminder)&&inside&&!m.geofenceInside)||("leave".equals(m.locationReminder)&&!inside&&m.geofenceInside);m.geofenceInside=inside;V4Meta.put(c,e.id,m);if(fire)notify(c,e,m.locationReminder);}}catch(Exception ex){V4Log.error(c,"location",ex.toString());}finally{LocationReminderScheduler.schedule(c);}}
 private void notify(Context c,EventStore.Event e,String type){NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String ch="location_reminders_v4";if(Build.VERSION.SDK_INT>=26){NotificationChannel nc=new NotificationChannel(ch,AppSettings.tr(c,"تذكيرات الموقع","Location reminders"),NotificationManager.IMPORTANCE_HIGH);n.createNotificationChannel(nc);}Intent open=new Intent(c,EditEventActivity.class).putExtra("event_id",e.id);PendingIntent pi=PendingIntent.getActivity(c,(int)e.id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String text="arrive".equals(type)?AppSettings.tr(c,"وصلت إلى موقع المناسبة","You arrived at the event location"):AppSettings.tr(c,"غادرت موقع المناسبة","You left the event location");Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,ch):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_dialog_map).setContentTitle(e.title).setContentText(text).setAutoCancel(true).setContentIntent(pi);n.notify((int)(e.id&0x7fffffff),b.build());V4Meta.Meta m=V4Meta.get(c,e.id);m.lastAlertAt=System.currentTimeMillis();V4Meta.put(c,e.id,m);V4Log.history(c,e.id,"location_alert",text);}
}
